#!/usr/bin/env bash\n\n# Test suite for nightly-disk-dragon utility\n# This script creates a temporary mock `df` command to simulate different disk usage scenarios.\n# No external network calls are made – everything runs locally.\n\nset -euo pipefail\n\n# Directory of the utility (relative to repository root)\nUTIL_DIR="../src"\nSCRIPT="$UTIL_DIR/disk_dragon.sh"\n\n# Helper to create a temporary mock `df` binary\ncreate_mock_df() {\n  local content="$1"\n  local mock_dir=$(mktemp -d)\n  cat > "$mock_dir/df" <<'EOS'\n#!/usr/bin/env bash\ncat <<'EOF'\n$CONTENT\nEOF\nEOS\n  chmod +x "$mock_dir/df"\n  echo "$mock_dir"\n}\n\n# Test case 1: usage above threshold should trigger a warning\nmock_output1='Filesystem 1024-blocks Used Available Capacity Mounted on\n/dev/sda1 1000000 900000 100000 90% /'\nmock_dir1=$(mktemp -d)\ncat > "$mock_dir1/df" <<'EOS'\n#!/usr/bin/env bash\ncat <<'EOF'\nFilesystem 1024-blocks Used Available Capacity Mounted on\n/dev/sda1 1000000 900000 100000 90% /\nEOF\nEOS\nchmod +x "$mock_dir1/df"\nPATH="$mock_dir1:$PATH"\noutput1=$(bash "$SCRIPT" -t 80)\nif ! grep -q "Dragon warns" <<< "$output1"; then\n  echo "Test 1 FAILED: Expected warning not found"\n  exit 1\nfi\n\n# Test case 2: usage below threshold should produce no warning\nmock_dir2=$(mktemp -d)\ncat > "$mock_dir2/df" <<'EOS'\n#!/usr/bin/env bash\ncat <<'EOF'\nFilesystem 1024-blocks Used Available Capacity Mounted on\n/dev/sda1 1000000 400000 600000 40% /\nEOF\nEOS\nchmod +x "$mock_dir2/df"\nPATH="$mock_dir2:$PATH"\noutput2=$(bash "$SCRIPT" -t 80)\nif grep -q "Dragon warns" <<< "$output2"; then\n  echo "Test 2 FAILED: Unexpected warning found"\n  exit 1\nfi\n\n# Clean up temporary mock directories\nrm -rf "$mock_dir1" "$mock_dir2"\n\necho "All tests passed"\n
